#[test]
fn from_str_base_unit() {
    let abbr = TorqueUnit::NewtonMeter.abbreviation();
    let s = format!("1 {}", abbr);
    let parsed: Torque = s.parse().expect("parse failed");
    let expected = Torque::from_newton_meters(1.0).as_base();
    assert!((parsed.as_base() - expected).abs() / expected.abs().max(1.0) < RT_EPS);
}
